/**
 * DSAForge seed — creates a demo user with 50+ solved questions and a
 * realistic, back-dated revision history generated by REPLAYING the real
 * spaced-repetition engine (so streaks, queues and memory scores are genuine).
 *
 *   npm run seed          # seed if the demo user doesn't exist
 *   npm run seed:fresh    # drop the database first
 */
import mongoose from 'mongoose';
import { connectDB, disconnectDB } from './src/config/db.js';
import User from './src/models/User.js';
import Question from './src/models/Question.js';
import Revision from './src/models/Revision.js';
import DailyActivity from './src/models/DailyActivity.js';
import seedQuestions from './src/data/seedQuestions.js';
import {
  computeNextInterval,
  computeMemoryStrength,
  computeWeakFlags,
  deriveRevisionStatus,
} from './src/services/spacedRepetition.js';
import { keyToUtcDate } from './src/utils/dates.js';

const DEMO_EMAIL = 'demo@dsaforge.app';
const DEMO_PASSWORD = 'demo1234';

/** Deterministic PRNG so reseeds produce the same history. */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function rng() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const keyOf = (d) => new Date(d).toISOString().slice(0, 10);
const addDays = (d, n) => new Date(d.getTime() + n * 86400000);

/**
 * Each question gets a memory profile so the demo bank contains genuine
 * mastered, learning and struggling questions (not uniform noise).
 */
function makeProfile(rng, difficulty) {
  let p = rng();
  if (difficulty === 'Hard') p -= 0.28;
  if (difficulty === 'Easy') p += 0.15;
  if (p > 0.55) return 'strong';
  if (p > 0.28) return 'medium';
  return 'weak';
}

function pickResult(profile, rng) {
  const roll = rng();
  if (profile === 'strong') {
    if (roll < 0.03) return 'forgot';
    if (roll < 0.08) return 'hard';
    if (roll < 0.44) return 'good';
    return 'easy';
  }
  if (profile === 'medium') {
    if (roll < 0.1) return 'forgot';
    if (roll < 0.4) return 'hard';
    if (roll < 0.82) return 'good';
    return 'easy';
  }
  if (roll < 0.6) return 'forgot';
  if (roll < 0.85) return 'hard';
  if (roll < 0.98) return 'good';
  return 'easy';
}

const MISTAKES = [
  { forgotWhat: 'The core trick of reducing the problem to a known pattern.', mistake: 'Went for the brute-force nested loop first and forgot the optimisation entirely.' },
  { gotStuck: 'Lost 10 minutes because I did not define what left/right represent.', insight: 'Always write down the loop invariant before coding.' },
  { forgotWhat: 'Base case / termination condition of the recursion.', mistake: 'Off-by-one in the base case — infinite recursion on the edge input.' },
  { insight: 'Draw the state transition table first; the recurrence writes itself.' },
  { mistake: 'Mutated the input array while iterating, which corrupted later comparisons.' },
  { forgotWhat: 'That a monotonic deque gives the sliding-window extremum in O(n).', insight: 'Whenever a window needs min/max, think monotonic deque first.' },
];

async function main() {
  const fresh = process.argv.includes('--fresh');
  await connectDB();

  if (fresh) {
    await mongoose.connection.dropDatabase();
    console.log('[seed] dropped database');
  }

  let user = await User.findOne({ email: DEMO_EMAIL });
  if (!user) {
    user = await User.create({
      name: 'Demo DSA Runner',
      email: DEMO_EMAIL,
      password: DEMO_PASSWORD,
      preferences: { dailyRevisionGoal: 12, dailySolveGoal: 3 },
    });
    console.log(`[seed] created user ${DEMO_EMAIL} / ${DEMO_PASSWORD}`);
  } else {
    const existing = await Question.countDocuments({ userId: user._id });
    if (existing > 0 && !fresh) {
      console.log(`[seed] user already has ${existing} questions — use --fresh to reseed`);
      await disconnectDB();
      return;
    }
  }

  const today = new Date();
  const todayKey = keyOf(today);

  const activity = new Map(); // dateKey → {solved, revised, results}
  const getActivity = (key) => {
    if (!activity.has(key)) activity.set(key, { solved: 0, revised: 0, results: { forgot: 0, hard: 0, good: 0, easy: 0 } });
    return activity.get(key);
  };
  const bump = (key, kind, result) => {
    if (!key || key > todayKey) return;
    const a = getActivity(key);
    if (kind === 'solved') a.solved += 1;
    else {
      a.revised += 1;
      a.results[result] += 1;
    }
  };
  const unbump = (key, kind, result) => {
    if (!key || !activity.has(key)) return;
    const a = activity.get(key);
    if (kind === 'solved') a.solved = Math.max(0, a.solved - 1);
    else {
      a.revised = Math.max(0, a.revised - 1);
      if (result) a.results[result] = Math.max(0, a.results[result] - 1);
    }
  };

  const questionDocs = [];
  const revisionDocs = [];

  seedQuestions.forEach((seed, i) => {
    const rng = mulberry32(1000 + i * 7);
    const difficulty = seed.difficulty || 'Medium';
    const profile = makeProfile(rng, difficulty);

    // Solve date spread: strong-profile questions are older so they have had
    // time to accumulate a real revision history.
    const daysAgoSolve = profile === 'strong' ? 60 + Math.floor(rng() * 75) : 25 + Math.floor(rng() * 65);
    const solvedAt = addDays(today, -daysAgoSolve);
    solvedAt.setHours(10 + Math.floor(rng() * 8), Math.floor(rng() * 60), 0, 0);
    const solvedDateKey = keyOf(solvedAt);

    // --- replay the SRS engine for this question --------------------------
    let lastReviewedAt = null;
    let cursor = new Date(solvedAt);
    let interval = 0;
    let count = 0;
    let results = [];
    let lastResult = null;
    let streak = 0;
    let strength = 50;
    let weakFlags = [];
    const mistakes = [];
    const maxCount = profile === 'strong' ? 12 : 9;

    while (count < maxCount) {
      const result = count === 0 && rng() < 0.5 ? 'good' : pickResult(profile, rng);
      const gap = count === 0 ? 0 : Math.max(1, Math.round((cursor.getTime() - lastReviewedAt.getTime()) / 86400000));

      const nextInterval = computeNextInterval({
        previousInterval: interval,
        revisionCount: count,
        result,
        actualGapDays: gap,
      });

      results = results.concat(result);
      count += 1;
      strength = computeMemoryStrength({
        results,
        revisionCount: count,
        intervalDays: nextInterval,
        daysSinceLastReview: 0,
      });
      weakFlags = computeWeakFlags({ results, memoryStrength: strength, revisionCount: count });
      streak = result === 'good' || result === 'easy' ? streak + 1 : 0;

      const reviewedAt = new Date(cursor);
      reviewedAt.setHours(9 + Math.floor(rng() * 10), Math.floor(rng() * 60), 0, 0);
      const dateKey = keyOf(reviewedAt);
      const nextReviewDate = addDays(new Date(`${dateKey}T00:00:00.000Z`), nextInterval);

      revisionDocs.push({
        userId: user._id,
        questionId: null,
        seedQuestionIndex: i,
        status: 'completed',
        startedAt: reviewedAt,
        reviewedAt,
        dateKey,
        result,
        previousInterval: interval,
        nextInterval,
        nextReviewDate,
        memoryStrengthBefore: count === 1 ? 50 : null,
        memoryStrengthAfter: strength,
        recalledApproach: '',
        mode: rng() < 0.25 ? 'deep' : 'quick',
        secondsSpent: 60 + Math.floor(rng() * 420),
        createdAt: reviewedAt,
        updatedAt: reviewedAt,
      });
      bump(dateKey, 'revised', result);

      if ((result === 'forgot' || result === 'hard') && rng() < 0.45 && mistakes.length < 3) {
        const m = MISTAKES[Math.floor(rng() * MISTAKES.length)];
        mistakes.push({ ...m, result, reviewedAt });
      }

      interval = nextInterval;
      lastResult = result;
      lastReviewedAt = reviewedAt;
      cursor = addDays(new Date(`${dateKey}T00:00:00.000Z`), nextInterval);
      if (cursor > today) break;
      // Occasionally skip a scheduled day so some questions become overdue.
      if (rng() < 0.18) cursor = addDays(cursor, 2 + Math.floor(rng() * 6));
      if (cursor > today) break;
    }

    const nextReviewDate = addDays(new Date(`${keyOf(lastReviewedAt)}T00:00:00.000Z`), interval);
    const status = deriveRevisionStatus({ nextReviewDate, todayKey, memoryStrength: strength, interval });

    questionDocs.push({
      userId: user._id,
      title: seed.title,
      description: seed.description || '',
      examples: seed.examples || [],
      constraints: seed.constraints || [],
      hints: seed.hints || [],
      platform: seed.platform || 'LeetCode',
      externalLink: seed.url || '',
      difficulty,
      topics: seed.topics || [],
      companies: seed.companies || [],
      status: 'solved',
      notes: seed.notes || '',
      approach: seed.approach || '',
      code: seed.code || '',
      language: seed.language || 'JavaScript',
      timeComplexity: seed.timeComplexity || '',
      spaceComplexity: seed.spaceComplexity || '',
      solvedAt,
      solvedDateKey,
      revision: {
        nextReviewDate,
        lastReviewedAt,
        revisionCount: count,
        memoryStrength: strength,
        status,
        interval,
        lastResult,
        resultStreak: streak,
        weakFlags,
        totalRevisionSeconds: 60 * count,
      },
      mistakes,
      createdAt: solvedAt,
      updatedAt: lastReviewedAt,
      __profile: profile,
    });
    bump(solvedDateKey, 'solved');
  });

  const lastIndexOfQuestion = () => {
    const map = new Map();
    revisionDocs.forEach((r, idx) => map.set(r.seedQuestionIndex, idx));
    return map;
  };

  /* ------------------------------------------------------------------ *
   * 1) A few questions were ALREADY revised today (live habit numbers).  *
   *    One extra engine step is appended on today's date.               *
   * ------------------------------------------------------------------ */
  const stepIdx = Math.max(1, Math.floor(questionDocs.length / 7));
  let revisedToday = 0;
  for (let i = 3; i < questionDocs.length && revisedToday < 7; i += stepIdx) {
    const q = questionDocs[i];
    if (keyOf(q.revision.lastReviewedAt) === todayKey) continue;

    const rng = mulberry32(9000 + i);
    const result = pickResult(q.__profile, rng);
    const count = q.revision.revisionCount;
    const gap = Math.max(1, Math.round((today - q.revision.lastReviewedAt) / 86400000));
    const nextInterval = computeNextInterval({
      previousInterval: q.revision.interval,
      revisionCount: count,
      result,
      actualGapDays: gap,
    });

    const prevResults = revisionDocs
      .filter((r) => r.seedQuestionIndex === i)
      .map((r) => r.result);
    const results = prevResults.concat(result);
    const newCount = count + 1;
    const strength = computeMemoryStrength({
      results,
      revisionCount: newCount,
      intervalDays: nextInterval,
      daysSinceLastReview: 0,
    });
    const weakFlags = computeWeakFlags({ results, memoryStrength: strength, revisionCount: newCount });

    const reviewedAt = new Date(today);
    reviewedAt.setHours(7 + Math.floor(rng() * 6), Math.floor(rng() * 60), 0, 0);
    const dateKey = keyOf(reviewedAt);
    const nextReviewDate = addDays(new Date(`${dateKey}T00:00:00.000Z`), nextInterval);

    revisionDocs.push({
      userId: user._id,
      questionId: null,
      seedQuestionIndex: i,
      status: 'completed',
      startedAt: reviewedAt,
      reviewedAt,
      dateKey,
      result,
      previousInterval: q.revision.interval,
      nextInterval,
      nextReviewDate,
      memoryStrengthBefore: q.revision.memoryStrength,
      memoryStrengthAfter: strength,
      recalledApproach: '',
      mode: 'quick',
      secondsSpent: 60 + Math.floor(rng() * 300),
      createdAt: reviewedAt,
      updatedAt: reviewedAt,
    });
    bump(dateKey, 'revised', result);

    q.revision = {
      ...q.revision,
      lastReviewedAt: reviewedAt,
      revisionCount: newCount,
      memoryStrength: strength,
      interval: nextInterval,
      lastResult: result,
      resultStreak: result === 'good' || result === 'easy' ? (q.revision.resultStreak || 0) + 1 : 0,
      weakFlags,
      status: deriveRevisionStatus({ nextReviewDate, todayKey, memoryStrength: strength, interval: nextInterval }),
      nextReviewDate,
      totalRevisionSeconds: (q.revision.totalRevisionSeconds || 0) + 120,
    };
    revisedToday++;
  }

  /* ------------------------------------------------------------------ *
   * 2) A few questions were solved TODAY (habit: solved today > 0) and   *
   *    are due for their first revision immediately.                    *
   * ------------------------------------------------------------------ */
  const freshIdx = [1, 14, 40];
  for (const i of freshIdx) {
    const q = questionDocs[i];
    if (!q) continue;

    // Remove every replayed revision row of this question + reverse activity.
    for (let k = revisionDocs.length - 1; k >= 0; k--) {
      if (revisionDocs[k].seedQuestionIndex === i) {
        const rd = revisionDocs[k];
        unbump(rd.dateKey, 'revised', rd.result);
        revisionDocs.splice(k, 1);
      }
    }
    unbump(q.solvedDateKey, 'solved');

    const solved = new Date(today);
    solved.setHours(7 + (i % 6), (i * 7) % 60, 0, 0);
    q.solvedAt = solved;
    q.solvedDateKey = todayKey;
    q.revision = {
      nextReviewDate: keyToUtcDate(todayKey),
      lastReviewedAt: null,
      revisionCount: 0,
      memoryStrength: 50,
      status: 'due',
      interval: 0,
      lastResult: null,
      resultStreak: 0,
      weakFlags: [],
      totalRevisionSeconds: 0,
    };
    q.mistakes = [];
    q.createdAt = solved;
    q.updatedAt = solved;
    bump(todayKey, 'solved');
  }

  /* ------------------------------------------------------------------ *
   * 3) Pin a slice of questions to be due TODAY so the demo queue has     *
   *    a realistic "Due Today" bucket.                                  *
   * ------------------------------------------------------------------ */
  const pinCandidates = questionDocs.filter((q) => {
    const last = q.revision.lastReviewedAt;
    if (!last) return false;
    if (keyOf(last) === todayKey) return false; // already revised today
    if (q.revision.revisionCount < 2) return false;
    const gap = Math.round((today - last) / 86400000);
    return gap >= 1 && gap <= 45;
  });
  const pinCount = Math.min(14, pinCandidates.length);
  const stride = Math.max(1, Math.floor(pinCandidates.length / pinCount));
  const lastIdxMap = lastIndexOfQuestion();
  let pinned = 0;
  for (let i = 0; i < pinCandidates.length && pinned < pinCount; i += stride) {
    const q = pinCandidates[i];
    const gap = Math.max(1, Math.round((today - q.revision.lastReviewedAt) / 86400000));
    q.revision.nextReviewDate = keyToUtcDate(todayKey);
    q.revision.interval = gap;
    q.revision.status = 'due';
    const idx = questionDocs.indexOf(q);
    const revIdx = lastIdxMap.get(idx);
    if (revIdx !== undefined && revisionDocs[revIdx]) {
      revisionDocs[revIdx].nextInterval = gap;
      revisionDocs[revIdx].nextReviewDate = keyToUtcDate(todayKey);
    }
    pinned++;
  }

  const inserted = await Question.insertMany(questionDocs.map(({ __profile, ...doc }) => doc));
  console.log(`[seed] inserted ${inserted.length} questions`);

  revisionDocs.forEach((r) => {
    r.questionId = inserted[r.seedQuestionIndex]._id;
    delete r.seedQuestionIndex;
  });
  if (revisionDocs.length) {
    await Revision.insertMany(revisionDocs, { ordered: false });
    console.log(`[seed] inserted ${revisionDocs.length} revision records`);
  }

  const activityDocs = [...activity.entries()]
    .filter(([key, a]) => key <= todayKey && (a.revised > 0 || a.solved > 0))
    .map(([key, a]) => ({
      userId: user._id,
      date: key,
      solvedCount: a.solved,
      revisedCount: a.revised,
      results: a.results,
    }));
  if (activityDocs.length) {
    await DailyActivity.insertMany(activityDocs, { ordered: false });
    console.log(`[seed] inserted ${activityDocs.length} activity days`);
  }

  // Quick summary of the queues the demo user starts with.
  const start = new Date(`${todayKey}T00:00:00.000Z`);
  const tomorrowKey = keyOf(new Date(Date.parse(`${todayKey}T00:00:00Z`) + 86400000));
  const end = new Date(`${tomorrowKey}T00:00:00.000Z`);
  const [due, overdue, upcoming, mastered, forgotten, weak] = await Promise.all([
    Question.countDocuments({ userId: user._id, 'revision.nextReviewDate': { $gte: start, $lt: end } }),
    Question.countDocuments({ userId: user._id, 'revision.nextReviewDate': { $lt: start } }),
    Question.countDocuments({ userId: user._id, 'revision.nextReviewDate': { $gte: end } }),
    Question.countDocuments({ userId: user._id, 'revision.memoryStrength': { $gte: 85 } }),
    Question.countDocuments({ userId: user._id, 'revision.memoryStrength': { $lt: 25 } }),
    Question.countDocuments({
      userId: user._id,
      'revision.revisionCount': { $gte: 1 },
      'revision.memoryStrength': { $lt: 45 },
    }),
  ]);
  console.log(`[seed] queues → due today: ${due} · overdue: ${overdue} · upcoming: ${upcoming}`);
  console.log(`[seed] memory → mastered: ${mastered} · weak: ${weak} · forgotten: ${forgotten}`);
  console.log('[seed] done');
  await disconnectDB();
}

main().catch((err) => {
  console.error('[seed] failed:', err);
  process.exit(1);
});
